        free(result.key); // Clean up
        free(result.iv);  // Clean up
        result.key = NULL;
        result.iv = NULL;
        return result; // Malloc failed
    }

    // Create and initialize the encryption context
    ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) {
        free(result.key); // Clean up
        free(result.iv);  // Clean up
        free(ciphertext); // Clean up
        result.key = NULL;
        result.iv = NULL;
        return result; // Failed to create EVP_CIPHER_CTX
